def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            objects.append(cells)

    for cells in objects:
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        shape = {(r - r0, c - c0) for r, c in cells}
        height, width = r1 - r0 + 1, c1 - c0 + 1

        vertical_symmetric = all((r, width - 1 - c) in shape for r, c in shape)
        horizontal_symmetric = all((height - 1 - r, c) in shape for r, c in shape)

        if not vertical_symmetric and not horizontal_symmetric:
            return [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
